#!/bin/sh
# Runs ONLY on disposable CI snapshot generated by isolated_snapshot_smoke.sh.
set -eu
SNAPSHOT_DIR="$1"
SNAPSHOTS_ROOT="$2"
PROMTOOL="$3"
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
ARCHIVE="$TMP/snapshot.tar.gz"
SNAPSHOT_ID="$(basename "$SNAPSHOT_DIR")"
ARCHIVE="$ARCHIVE" SNAPSHOT_ID="$SNAPSHOT_ID" SNAPSHOT_DIR="$SNAPSHOT_DIR" SNAPSHOTS_ROOT="$SNAPSHOTS_ROOT" PROMTOOL="$PROMTOOL" python3 - <<'PY'
import hashlib
import os
import pathlib
import sys
import tarfile
import tempfile
import threading
from http.server import ThreadingHTTPServer
sys.path.insert(0, str(pathlib.Path("ops/prometheus").resolve()))
import backup_receiver
import backup_once
import backup_coordinator
import snapshot_controller
archive = pathlib.Path(os.environ["ARCHIVE"])
blocks = {p.name for p in pathlib.Path(os.environ["SNAPSHOT_DIR"]).iterdir() if p.is_dir()}
if not blocks:
    raise RuntimeError("No blocks in synthetic snapshot")
with tempfile.TemporaryDirectory() as backup:
    server = ThreadingHTTPServer(("127.0.0.1", 0), backup_receiver.make_handler(pathlib.Path(backup), "x"*32, os.environ["PROMTOOL"], False))
    server.upload_busy = False
    worker = threading.Thread(target=server.serve_forever, daemon=True)
    worker.start()
    try:
        # Real loopback controller forwards to the already-running disposable Prometheus.
        controller = ThreadingHTTPServer(("127.0.0.1", 19092), snapshot_controller.Handler)
        controller_worker = threading.Thread(target=controller.serve_forever, daemon=True)
        controller_worker.start()
        try:
            os.environ["PROMETHEUS_SNAPSHOT_CONTROLLER_TOKEN"] = "y"*32
            result = backup_coordinator.coordinate(
                os.environ["SNAPSHOTS_ROOT"], archive.parent,
                f"http://127.0.0.1:{server.server_port}/v1/upload",
                "x"*32, "y"*32, archive.parent / "coordinator.lock"
            )
        finally:
            controller.shutdown()
            controller.server_close()
            os.environ.pop("PROMETHEUS_SNAPSHOT_CONTROLLER_TOKEN", None)
        generated = list(archive.parent.glob("snapshot-*.tar.gz"))
        assert len(generated) == 1, generated
        archive = generated[0]
        assert result["status"] == "verified", result
        assert result["restore_test"] == "promtool-tsdb-analyze-pass", result
        assert result["sha256"] == hashlib.sha256(archive.read_bytes()).hexdigest()
        assert len(list(pathlib.Path(backup).glob("*.tar.gz"))) == 1
        print("REAL_COORDINATOR_RECEIVER_PROMTOOL_E2E_PASS", flush=True)
    finally:
        server.shutdown()
        server.server_close()
PY
